// Tracks and signs of the Pidwa mammals: what the spoor looks like, how big it is, the dung, the other signs.
// The data (tracks.data.json) is generated by data/scripts/tmp/build-tracks.mjs from the species sheets of Gutteridge &
// Liebenberg, "Mammals of Southern Africa and their Tracks & Signs" (Jacana, 2013): lengths are the ones printed next to
// the drawings (measured mostly at Londolozi, Sabi Sand), widths come from the proportions of the traced drawings, and the
// texts are our rewording of the sheets. The drawings themselves are served from data/out/spoor/paths.json.
import DATA from './tracks.data.json';

/** Print family: drives the "Print" label and the fallback drawing template when the traced drawing is missing. */
export type Shape =
  | 'cloven'   // two hoof halves: antelope, buffalo, giraffe, pigs
  | 'cat'      // four toes, no claws, pad with a three-lobed rear
  | 'dog'      // four toes with claws, slim pad with a two-lobed rear
  | 'hyena'    // four toes with blunt claws, big pad, front much larger than hind
  | 'hoof'     // one round hoof: zebra
  | 'round'    // big round or oval sole: elephant, rhino, hippo
  | 'hand'     // five fingers with a thumb: baboon, monkey, bushbaby
  | 'digger'   // five toes with long claws: aardvark, pangolin, honey badger, porcupine
  | 'small';   // the small carnivores, hyrax, hare and rodents

export interface Foot { l: number; w: number }   // length and width in cm, claws excluded

export interface Spoor {
  id: string;            // species id of the checklist
  shape: Shape;
  front: Foot;
  hind: Foot;
  /** Template parameters of the fallback drawing (cloven only): 0 = pointed hoof tips, 1 = rounded; gap between halves, cm. */
  blunt?: number;
  cleft?: number;
  toes: number;          // toes that show in the print (hoof halves for cloven)
  claws: boolean;        // claw marks usually show
  clawsNote?: string;    // the sheet's wording: show / sometimes / usually hidden / never show
  dew: boolean;          // dew claws or false hooves usually show in the print
  /** Full entries only (shown on the species page). */
  track?: string;        // what the print looks like, and what sets it apart
  trail?: string;        // gait, register, what the line of prints tells you
  dung?: string;
  signs?: string[];      // feeding signs, dens, rubbing posts, scent marks…
  facts?: string[];      // memorable field facts
  confuse?: string[];    // species ids (or plain names) drawn next to it at the same scale
  why?: Record<string, string>;   // for each confusable, the criterion that separates them
  widthMm?: { front?: number | null; hind?: number | null };
}

export const SPOOR = DATA as Spoor[];

export const spoorById = new Map(SPOOR.map((s) => [s.id, s]));

export const SHAPE_LABEL: Record<Shape, string> = {
  cloven: 'cloven hoof', cat: 'cat paw', dog: 'dog paw', hyena: 'hyena paw', hoof: 'single hoof', round: 'round sole',
  hand: 'hand-like', digger: 'clawed paw', small: 'small paw',
};

/** What a print looks like at first glance, for the footprint key and the quiz: label and a typical species for the tile.
    Some species sit in two families because the book says they are taken for either (the civet's print reads as a cat's to
    a novice and is confused with a jackal's). */
export const LOOKS: [string, string, string][] = [
  ['cloven', 'Split hoof', 'aepyceros-melampus'],
  ['hoof', 'Single hoof', 'equus-quagga'],
  ['giant', 'Giant foot', 'ceratotherium-simum'],
  ['cat', 'Cat-like paw', 'panthera-pardus'],
  ['dog', 'Dog-like paw', 'lupulella-mesomelas'],
  ['five', 'Five toes', 'atilax-paludinosus'],
  ['hand', 'Hand-like', 'papio-ursinus'],
  ['other', 'Hare, hyrax, rat', 'lepus-saxatilis'],
];
const EXTRA_LOOK: Record<string, string[]> = {
  'civettictis-civetta': ['cat', 'dog'], 'genetta-tigrina': ['cat'], 'genetta-genetta': ['cat'], 'ichneumia-albicauda': ['dog'],
};
export function looksOf(e: Spoor): string[] {
  if (EXTRA_LOOK[e.id]) return EXTRA_LOOK[e.id];
  switch (e.shape) {
    case 'cloven': case 'hoof': case 'cat': case 'dog': case 'hand': return [e.shape];
    case 'hyena': return ['dog'];
    case 'round': return ['giant'];
    case 'digger': return ['five'];
    default: return e.toes >= 5 ? ['five'] : ['other'];
  }
}
